t.fillStyle="rgba(0, 0, 0, 0.4)";t.fillRect(75,1150,930,120);t.strokeStyle="rgba(255, 255, 255, 0.1)";t.strokeRect(75,1150,930,120);t.fillStyle="#58a6ff";t.font="bold 20px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";t.fillText("COMMAND CENTER GRAVITY Ã¢â‚¬Â¢ NIGERIAN POETIC ATLAS",100,1195);t.fillStyle="rgba(255, 255, 255, 0.55)";t.font="18px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";t.fillText("Grounded in living spoken word archives, literary circuits & real communities",100,1230);
